properties.query:
// Cheap equality/isnotempty filters (DeviceProduct, AlertEvidence, RequestBody, ResponseBody, minimum
// marker length to cut noise from trivial evidence strings) run before the two `contains` substring
// scans. `contains` (not `has`) is used deliberately - AlertEvidence payload markers routinely include
// punctuation (e.g. <script>, quotes) that breaks `has`'s word-boundary tokenization and would silently
// under-match; the extra scan cost is the point of this rule (proof over heuristic).
PrancerFindings
| where DeviceProduct == 'dast'
| where isnotempty(AlertEvidence)
| where strlen(AlertEvidence) >= 6
| where isnotempty(RequestBody) and isnotempty(ResponseBody)
| where RequestBody contains AlertEvidence
| where ResponseBody contains AlertEvidence
| extend ExploitationProof = 'Injected payload marker confirmed present in both request and response body'
| project
    FindingId, ConfigId, CustomerId, CompanyName, Title, Severity, CweId, MitreIds, AlertEvidence,
    AlertSolution, ResourceUrl, ResourceID, ApplicationName, RequestBody, ResponseBody, ExploitationProof, TimeGenerated

// Cheap filters (isnotempty ResourceID/ResourceUrl) run before the watchlist join. The watchlist is small
// (customer-declared, not per-finding), so joining it in is cheap regardless of which side is "left".
// _GetWatchlist() flattens the watchlist's CSV columns into named top-level columns matching the CSV
// header (ResourceId, AssetName, CriticalityTier, AssetCategory, Owner, Notes) once watchlist items have
// propagated - live-confirmed against a real deployed watchlist (2026-08-12), 4 real findings correctly
// matched. Caution for future maintainers: querying _GetWatchlist() against a watchlist with zero
// propagated items returns a different, generic placeholder schema (_DTItemId/LastUpdatedTimeUTC/
// SearchKey/WatchlistItem-as-dynamic) that can look like the "real" schema but isn't - always verify
// against a watchlist with at least one real item present, not an empty one.
let CrownJewelWatchlist = (_GetWatchlist('PrancerCrownJewelAssets')
    | project
        WatchlistResourceId = ResourceId,
        AssetName,
        CriticalityTier,
        AssetCategory,
        Owner);
let SeverityRankFn = (sev: string) {
    case(
        sev == 'Critical', 1,
        sev == 'High', 2,
        sev == 'Medium', 3,
        sev == 'Low', 4,
        sev == 'Info' or sev == 'Informational', 5,
        99
    )
};
PrancerFindings
| where isnotempty(ResourceID) or isnotempty(ResourceUrl)
| extend MatchKey = iff(isnotempty(ResourceID), ResourceID, ResourceUrl)
| join kind=inner (CrownJewelWatchlist) on $left.MatchKey == $right.WatchlistResourceId
| extend
    NominalSeverityRank = SeverityRankFn(Severity),
    DeclaredSeverityRank = SeverityRankFn(CriticalityTier)
| where DeclaredSeverityRank < NominalSeverityRank
| extend
    EscalatedSeverity = CriticalityTier,
    EscalationReason = strcat(
        'Nominal severity ', Severity, ' escalated to ', CriticalityTier, ': resource matches watchlist-declared crown jewel "',
        AssetName, '" (', AssetCategory, ', owner: ', Owner, ')')
// MatchKey is whichever of ResourceID/ResourceUrl the watchlist match came from - split it back
// into type-specific columns so entity mapping doesn't tag a URL as an AzureResource ResourceId.
| extend
    MatchedResourceId = iff(isnotempty(ResourceID), MatchKey, ''),
    MatchedUrl = iff(isnotempty(ResourceID), '', MatchKey)

// DeviceProduct == 'swarmhack' and isnotempty(RiskScore)/isnotempty(Confidence) run before the
// divergence-category classification and DivergenceScore computation.
let HighRiskThreshold = 7.0;
let LowRiskThreshold = 3.0;
let LowConfidenceThreshold = 0.4;
let HighConfidenceThreshold = 0.75;
PrancerFindings
| where DeviceProduct == 'swarmhack'
| where isnotempty(RiskScore) and isnotempty(Confidence)
| extend DivergenceCategory = case(
    RiskScore >= HighRiskThreshold and Confidence <= LowConfidenceThreshold, 'high_risk_low_confidence_needs_verification',
    RiskScore <= LowRiskThreshold and Confidence >= HighConfidenceThreshold, 'low_risk_high_confidence_may_be_underrated',
    'aligned')
| where DivergenceCategory != 'aligned'
| extend DivergenceScore = round(abs((RiskScore / 10.0) - Confidence), 3)
| project
    FindingId, ConfigId, CustomerId, CompanyName, Title, Severity, RiskScore, Confidence,
    DivergenceCategory, DivergenceScore, KillChain, CrownJewels, ResourceID, ResourceUrl, TimeGenerated
| order by DivergenceScore desc
